function countDigitAppearances(n, d) {
    let count = 0n;
    let m = 1n;
    const bn = BigInt(n);
    const bd = BigInt(d);
    while (m <= bn) {
        const higher = bn / (m * 10n);
        const cur = (bn / m) % 10n;
        const lower = bn % m;
        if (bd === 0n) {
            if (higher > 0n) count += (higher - 1n) * m;
            else { m *= 10n; continue; }
            if (cur === 0n) count += lower + 1n;
            else count += m;
        } else {
            count += higher * m;
            if (cur === bd) count += lower + 1n;
            else if (cur > bd) count += m;
        }
        m *= 10n;
    }
    return Number(count);
}
